<template>
  <q-page class="payment-page"><main>
    <nav><q-btn flat no-caps icon="arrow_back" label="Minhas marcações" to="/minhas-marcacoes" /></nav>
    <header><span><q-icon name="verified_user" /> PAGAMENTO PROTEGIDO</span><h1>Confirmar pagamento</h1><p>Pague com M-Pesa. O salão só recebe depois da confirmação do serviço.</p></header>
    <q-banner v-if="error" rounded class="error"><q-icon name="error_outline" /> {{ error }}</q-banner>
    <q-skeleton v-if="loading" height="400px" class="card" />
    <section v-else-if="appointment" class="layout">
      <article class="card summary"><div class="summary-top"><span class="brand"><q-icon name="phone_android" /> M‑Pesa</span><span class="secure"><q-icon name="lock" /> Seguro</span></div><small class="section-label">RESUMO DA MARCAÇÃO</small><h2>{{ appointment.serviceName }}</h2><p><q-icon name="storefront" /> {{ appointment.salonName }}</p>
        <dl><div><dt><q-icon name="calendar_today" /> Data e hora</dt><dd>{{ date(appointment.startsAt) }}</dd></div><div class="total"><dt>Total a pagar</dt><dd>{{ money(appointment.total) }}</dd></div></dl>
        <q-form v-if="!payment || retryable" ref="paymentForm" class="pay-form" @submit.prevent="pay"><q-input v-model="phone" outlined label="Número M-Pesa" prefix="+258" mask="## ### ####" unmasked-value lazy-rules :rules="[validatePhone]" hint="Introduza o número que receberá o pedido M-Pesa"><template #prepend><q-icon name="phone_android" /></template></q-input><q-btn type="submit" unelevated rounded no-caps color="primary" icon="lock" label="Pagar com M-Pesa" :loading="paying" :disable="paying" /></q-form>
        <div v-else class="state" :class="payment.status.toLowerCase()"><q-icon :name="stateIcon" /><div><small>{{ statusLabel }}</small><strong>{{ payment.reference }}</strong><p>{{ payment.providerMessage }}</p></div></div>
      </article>
      <aside class="card protection"><div class="protection-title"><span><q-icon name="shield" /></span><div><small>PROTEÇÃO SHONGA</small><h3>O seu dinheiro está seguro</h3></div></div><ol><li><span><q-icon name="phone_iphone" /></span><div><b>Autorize no telemóvel</b><small>Confirme o pedido enviado pelo M-Pesa.</small></div></li><li><span><q-icon name="lock_clock" /></span><div><b>Valor protegido</b><small>O pagamento fica retido pela Shonga.</small></div></li><li><span><q-icon name="qr_code_2" /></span><div><b>Confirme no final</b><small>Use o PIN ou QR somente após o serviço.</small></div></li></ol><p v-if="payment" class="split"><span><small>Salão recebe</small><b>{{ money(payment.salonAmount) }}</b></span><span><small>Comissão</small><b>{{ money(payment.commissionAmount) }}</b></span></p></aside>
      <article v-if="payment?.status === 'HELD' && credentials" class="card confirmation"><div class="confirmation-copy"><span class="ok"><q-icon name="check" /></span><div><small>PAGAMENTO CONFIRMADO</small><h2>Valor protegido com sucesso</h2><p>Guarde este código. Use-o apenas no fim do atendimento para confirmar que o serviço foi realizado.</p></div></div><div class="proof"><div class="pin-box"><small>PIN DO SERVIÇO</small><strong>{{ credentials.pin }}</strong><span><q-icon name="visibility_off" /> Não partilhe antes do atendimento</span></div><div class="qr-box"><img :src="qrDataUrl" alt="QR Code para confirmar o serviço" /><small>QR DE CONFIRMAÇÃO</small></div></div><div class="self-confirm"><q-icon name="info_outline" /><span><b>Já terminou o atendimento?</b><small>Também pode confirmar introduzindo o PIN abaixo.</small></span></div><q-input v-model="proof" outlined label="PIN de 6 dígitos" mask="######" unmasked-value maxlength="6"><template #append><q-btn flat dense no-caps label="Confirmar" :disable="proof.length !== 6" :loading="confirming" @click="confirm" /></template></q-input><q-btn class="dispute-link" flat no-caps color="negative" icon="report_problem" label="Reportar problema com o serviço" @click="disputeDialog=true" /></article>
      <article v-if="payment?.status === 'RELEASED'" class="card done">
        <div class="done-hero"><span><q-icon name="check" /></span><small>ATENDIMENTO FINALIZADO</small><h2>Serviço concluído</h2><p>A confirmação foi registada e o pagamento libertado ao salão com sucesso.</p></div>
        <div class="done-receipt"><div class="receipt-service"><span><q-icon name="content_cut" /></span><div><small>SERVIÇO</small><strong>{{ appointment.serviceName }}</strong><p>{{ appointment.salonName }}</p></div></div><dl><div><dt>Valor pago</dt><dd>{{ money(payment.amount) }}</dd></div><div><dt>Referência</dt><dd>{{ payment.reference }}</dd></div><div v-if="payment.releasedAt"><dt>Concluído em</dt><dd>{{ shortDate(payment.releasedAt) }}</dd></div></dl><div class="receipt-status"><q-icon name="verified_user" /><span><b>Pagamento entregue</b><small>O valor protegido já foi disponibilizado ao salão.</small></span></div></div>
        <div class="done-actions"><q-btn outline rounded no-caps color="primary" icon="home" label="Voltar ao início" to="/" /><q-btn unelevated rounded no-caps color="primary" icon="calendar_month" label="Minhas marcações" to="/minhas-marcacoes" /></div>
      </article>
    </section>
  </main><q-dialog v-model="disputeDialog"><q-card class="dispute-card"><q-card-section><span><q-icon name="gavel" /></span><small>PROTEÇÃO DO CLIENTE</small><h2>Abrir uma disputa?</h2><p>O valor continuará retido durante a análise. Se houver reembolso, receberá 97% do pagamento; 3% são a taxa não reembolsável da carteira móvel.</p><q-input v-model="disputeReason" outlined type="textarea" autogrow maxlength="1000" counter label="Descreva o problema" hint="Inclua detalhes do atendimento (mínimo de 10 caracteres)" /></q-card-section><q-card-actions><q-btn v-close-popup flat rounded no-caps label="Voltar" /><q-btn unelevated rounded no-caps color="negative" label="Abrir disputa" :disable="disputeReason.trim().length<10" :loading="disputing" @click="openDispute" /></q-card-actions></q-card></q-dialog></q-page>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { gql } from '@apollo/client/core'
import { useQuasar } from 'quasar'
import QRCode from 'qrcode'
import { apolloClient } from 'boot/apollo'
import { useAuthStore } from 'stores/auth-store'
const route=useRoute(),$q=useQuasar(),auth=useAuthStore(),appointmentId=String(route.params.appointmentId)
const loading=ref(true),paying=ref(false),confirming=ref(false),disputing=ref(false),disputeDialog=ref(false),disputeReason=ref(''),error=ref(''),phone=ref((auth.user?.phone??'').replace(/^(?:\+?258)/,'')),paymentForm=ref(null),appointment=ref(null),payment=ref(null),credentials=ref(null),qrDataUrl=ref(''),proof=ref('')
const LOAD=gql`query PaymentScreen($id:ID!){myAppointments{id salonName serviceName startsAt total status}appointmentPayment(appointmentId:$id){id reference status phone amount commissionAmount salonAmount providerMessage expiresAt releasedAt}}`
const PAY=gql`mutation Pay($id:ID!,$phone:String!){startMpesaPayment(appointmentId:$id,phone:$phone){id reference status phone amount commissionAmount salonAmount providerMessage expiresAt}}`
const CREDS=gql`query Credentials($id:ID!){serviceCredentials(appointmentId:$id){pin qrPayload expiresAt}}`
const CONFIRM=gql`mutation Confirm($id:ID!,$proof:String!){confirmService(appointmentId:$id,proof:$proof){id status reference releasedAt}}`
const DISPUTE=gql`mutation Dispute($id:ID!,$reason:String!){openPaymentDispute(appointmentId:$id,reason:$reason){id status reference providerMessage}}`
const retryable=computed(()=>['FAILED','EXPIRED','CANCELLED'].includes(payment.value?.status))
const stateIcon=computed(()=>({PENDING:'hourglass_top',HELD:'lock',DISPUTED:'gavel',FAILED:'error',EXPIRED:'timer_off'}[payment.value?.status]||'payments'))
const statusLabel=computed(()=>({CREATED:'Pedido criado',PENDING:'Aguarda autorização no telemóvel',HELD:'Pago · valor protegido',DISPUTED:'Pagamento em disputa',FAILED:'Pagamento falhou',EXPIRED:'Pedido expirado'}[payment.value?.status]||payment.value?.status))
async function load(){loading.value=true;error.value='';try{const{data}=await apolloClient.query({query:LOAD,variables:{id:appointmentId},fetchPolicy:'network-only'});appointment.value=data.myAppointments.find(x=>x.id===appointmentId);payment.value=data.appointmentPayment;if(!appointment.value)throw new Error('Marcação não encontrada');if(payment.value?.status==='HELD')await loadCredentials()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadCredentials(){const{data}=await apolloClient.query({query:CREDS,variables:{id:appointmentId},fetchPolicy:'network-only'});credentials.value=data.serviceCredentials;qrDataUrl.value=await QRCode.toDataURL(credentials.value.qrPayload,{width:220,margin:2,color:{dark:'#18231d',light:'#ffffff'}})}
const validatePhone=value=>/^8[234567]\d{7}$/.test(String(value).replace(/\D/g,''))||'Introduza um número M-Pesa válido, por exemplo 84 123 4567'
const errorMessage=e=>e?.graphQLErrors?.[0]?.message||e?.cause?.message||e?.message||'Não foi possível processar o pagamento'
async function pay(){const valid=await paymentForm.value?.validate();if(!valid){$q.notify({type:'warning',message:'Verifique o número M-Pesa'});return}paying.value=true;error.value='';$q.notify({type:'info',spinner:true,timeout:1500,message:'A enviar o pedido ao M-Pesa…'});try{const normalized=phone.value.replace(/\D/g,'');const{data}=await apolloClient.mutate({mutation:PAY,variables:{id:appointmentId,phone:normalized},fetchPolicy:'no-cache'});payment.value=data.startMpesaPayment;if(payment.value.status==='HELD'){await loadCredentials();$q.notify({type:'positive',message:'Pagamento confirmado. O valor está protegido.'})}else{$q.notify({type:'info',message:'Pedido enviado. Autorize-o no seu telemóvel.'})}}catch(e){error.value=errorMessage(e);$q.notify({type:'negative',message:error.value})}finally{paying.value=false}}
async function confirm(){confirming.value=true;error.value='';try{const{data}=await apolloClient.mutate({mutation:CONFIRM,variables:{id:appointmentId,proof:proof.value}});payment.value={...payment.value,...data.confirmService};credentials.value=null}catch(e){error.value=e.message}finally{confirming.value=false}}
async function openDispute(){disputing.value=true;error.value='';try{const{data}=await apolloClient.mutate({mutation:DISPUTE,variables:{id:appointmentId,reason:disputeReason.value.trim()}});payment.value={...payment.value,...data.openPaymentDispute};credentials.value=null;disputeDialog.value=false;$q.notify({type:'positive',message:'Disputa aberta. O valor permanece protegido.'})}catch(e){error.value=errorMessage(e);$q.notify({type:'negative',message:error.value})}finally{disputing.value=false}}
const money=v=>`${Number(v).toLocaleString('pt-MZ',{minimumFractionDigits:2})} MT`
const date=v=>new Intl.DateTimeFormat('pt-MZ',{dateStyle:'full',timeStyle:'short',timeZone:'Africa/Maputo'}).format(new Date(v))
const shortDate=v=>new Intl.DateTimeFormat('pt-MZ',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Maputo'}).format(new Date(v))
onMounted(load)
</script>

